namespace HdrPilot {
public static class UpdatePresentation { public static void ButtonStyle(Button button,FrameworkElement owner,bool available){button.Style=owner.TryFindResource(available?"UpdateAvailable":"UpdateAction") as Style;}
 public static string Summary(ModItem item,ModItem check){
  string current=String.IsNullOrWhiteSpace(item.Version)?Appearance.Localize("Installed revision unknown"):item.Version;
  string result=Appearance.Localize("Versione installata")+": "+current;
  if(ModUpdates.IsChecking(item.Game,item.Id))return result+"\n"+Appearance.Localize("Checking updates…");
  if(check==null)return result+"\n"+Appearance.Localize("Not checked");
  return result+"\n"+(String.IsNullOrEmpty(check.Latest)?"":Appearance.Localize("Versione disponibile")+": "+check.Latest+" · ")+Appearance.Localize(check.Status);
 }
 public static string Action(ModItem item,ModItem check){return Appearance.Localize("Update")+" "+(item.Id=="renodx"?"RenoDX HDR":item.Id=="effect"?"shader":item.Name)+(check==null||String.IsNullOrWhiteSpace(check.Latest)||check.Latest.Length>16?"":" · "+check.Latest);}
 public static void Paint(TextBlock text,ModItem check){text.Foreground=new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(230,172,80));if(check!=null&&(check.Status=="Version check unavailable"||check.Status=="Installed revision unknown"))StatusFeedback.Error(text,text.Text);}
}
public static class ModCenter {
 static bool ownBusy;public static bool Busy {get{return ownBusy||InlineOperation.IsBusy;}set{ownBusy=value;}}
 public static bool CanUpdate(ModItem item,ModItem check){return !ModUpdates.Checking&&(item.Id=="addon"||item.Id=="opti"||item.Id=="nr"||(item.Id=="ue4ss"&&check!=null&&check.Status=="Installed revision unknown")||(check!=null&&check.UpdateAvailable&&check.Status=="Update available"));}
 static string L(string s){return Appearance.Localize(s);}
 public static void Show(Window owner,IEnumerable<Game> games,Game selected,bool removal,Action changed){var all=games.Where(g=>g!=null&&File.Exists(g.Exe)).ToList();if(selected!=null&&!all.Any(g=>g.Exe==selected.Exe))all.Add(selected);StackPanel body;var d=Dialogs.Create(owner,L(removal?"Remove components":"Mod updates"),out body);d.Width=950;d.MaxHeight=SystemParameters.WorkArea.Height-40;var picker=new ComboBox{ItemsSource=all,DisplayMemberPath="Name",SelectedItem=selected??all.FirstOrDefault(),Margin=new Thickness(0,0,0,10)};body.Children.Add(picker);var info=Dialogs.Text(L(removal?"Remove one component at a time. Files are deleted with a recovery copy; other mods are preserved.":"Checks run at startup. Updates are applied only when you choose them, with backup."),13);body.Children.Add(info);var list=new StackPanel();body.Children.Add(new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,MaxHeight=420});var refresh=new Button{Content=L("Check again"),Margin=new Thickness(0,12,0,0)};body.Children.Add(refresh);Action render=null;
 Action<DlssPlan> review=plan=>{StackPanel b;var w=Dialogs.Create(d,L("Review changes"),out b);w.Width=830;b.Children.Add(new TextBox{Text=plan.ToString(),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,Height=330,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});var apply=new Button{Content=L("Apply with backup"),Margin=new Thickness(0,12,0,0)};b.Children.Add(apply);w.Closing+=(s,e)=>{if(Busy)e.Cancel=true;};apply.Click+=async(s,e)=>{Busy=true;apply.IsEnabled=false;try{string recovery=await Task.Run(()=>DlssCore.Apply((Game)picker.SelectedItem,plan));Busy=false;w.Close();info.Text=L("Files verified. Recovery copy:")+" "+recovery;changed();ModUpdates.AfterApply((Game)picker.SelectedItem,plan);render();}catch(Exception ex){StatusFeedback.Error(info,ex.Message);}finally{Busy=false;apply.IsEnabled=true;}};w.ShowDialog();};
 render=()=>{list.Children.Clear();var game=picker.SelectedItem as Game;if(game==null)return;foreach(var item in ModInventory.Scan(game)){var row=new DockPanel{Margin=new Thickness(0,6,0,6)};var action=new Button{Content=L(removal?(item.Id=="native"||item.Id=="streamline"?"Restore original":"Uninstall"):"Update"),Margin=new Thickness(12,0,0,0),MinWidth=110};DockPanel.SetDock(action,Dock.Bottom);row.Children.Add(action);string marker=item.Id=="asi"?AsiLoader.Marker:item.Id=="mfg"?MfgAddon.Marker:item.Id=="renodx"?RenoDx.AddonMarker:item.Id=="reshade"?RenoDx.Marker:item.Id=="nr"?NrModels.Marker:item.Id=="effect"?item.Marker:null;if(removal&&marker!=null&&File.Exists(Path.Combine(Path.GetDirectoryName(game.Exe),marker))){var undo=new Button{Content=L("Restore previous"),Margin=new Thickness(8,0,0,0)};DockPanel.SetDock(undo,Dock.Right);row.Children.Add(undo);undo.Click+=(s,e)=>{try{review(item.Id=="asi"?AsiLoader.Restore(game):item.Id=="mfg"?MfgAddon.Restore(game):item.Id=="nr"?NrModels.Restore(game):item.Id=="effect"?EffectCatalog.Remove(game,item.Effect):RenoDx.Restore(game,marker));}catch(Exception ex){StatusFeedback.Error(info,ex.Message);}};}var label=new Button{Content=item.Name+" · "+(item.Version??""),Style=d.TryFindResource("Installed") as Style,HorizontalContentAlignment=HorizontalAlignment.Left};var col=new StackPanel();col.Children.Add(label);if(!String.IsNullOrEmpty(item.File)){string prefix=Path.GetFullPath(game.Root).TrimEnd('\\')+"\\";string location=item.File.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)?item.File.Substring(prefix.Length):item.File;col.Children.Add(Dialogs.Text(location,11));}if(!removal){var check=ModUpdates.Items.FirstOrDefault(i=>i.Game.Exe==game.Exe&&i.Id==item.Id&&i.File==item.File&&i.Name==item.Name);action.IsEnabled=CanUpdate(item,check);UpdatePresentation.ButtonStyle(action,d,check!=null&&check.UpdateAvailable);var updateState=Dialogs.Text(UpdatePresentation.Summary(item,check),14);UpdatePresentation.Paint(updateState,check);col.Children.Add(updateState);if(!new[]{"opti","nr","addon"}.Contains(item.Id))action.Content=UpdatePresentation.Action(item,check);}row.Children.Add(col);list.Children.Add(row);action.Click+=async(s,e)=>{if(Busy)return;Busy=true;picker.IsEnabled=refresh.IsEnabled=list.IsEnabled=false;try{if(removal){var plan=ModInventory.Remove(item);Busy=false;review(plan);}else if(item.Id=="opti"||item.Id=="nr"||item.Id=="ue4ss"){Busy=false;if(item.Id=="opti")DlssUi.Show(d,game);else if(item.Id=="nr")NrModels.Show(d,game,DlssHardware.Detect().Series,changed);else{Busy=true;var plan=await Task.Run(()=>Ue4ssInstaller.DownloadAndPrepare(game,false));Busy=false;review(plan);}}else{var plan=await Task.Run(()=>Update(item));Busy=false;review(plan);}render();}catch(Exception ex){StatusFeedback.Error(info,ex.Message);}finally{Busy=false;picker.IsEnabled=refresh.IsEnabled=list.IsEnabled=true;}};}
 if(removal){if(File.Exists(Path.Combine(Path.GetDirectoryName(game.Exe),RenoDx.KeyMarker))){var restoreKey=new Button{Content=L("Ripristina tasto ReShade"),Margin=new Thickness(0,10,0,0)};list.Children.Add(restoreKey);restoreKey.Click+=(s,e)=>{try{review(RenoDx.Restore(game,RenoDx.KeyMarker));}catch(Exception ex){StatusFeedback.Error(info,ex.Message);}};}var duplicate=new Button{Content=L("Clean duplicate loaders"),Margin=new Thickness(0,12,0,0)};list.Children.Add(duplicate);duplicate.Click+=(s,e)=>{try{review(DuplicateLoaders.Prepare(game));}catch(Exception ex){StatusFeedback.Error(info,ex.Message);}};}
