  render=()=>{
   var items=ModInventory.Scan(game).Where(i=>dlss?new[]{"opti","nr","native","streamline"}.Contains(i.Id):!new[]{"opti","nr","native","streamline"}.Contains(i.Id)).Where(i=>(scope==null||(scope=="dll"?i.Id!="opti":i.Id==scope))&&(scope!="addon"||!RenoNr.Detected(game).Contains(i.File,StringComparer.OrdinalIgnoreCase))).ToList();removals.Children.Clear();updates.Children.Clear();
   hdr.Children.Clear();if(!dlss&&(scope==null||scope=="renodx")&&RenoGameHdr.Supported(game)){bool configured=RenoGameHdr.Configured(game);var row=new WrapPanel();var configure=new Button{Content=L(configured?"HDR configured":"Configure HDR"),Margin=new Thickness(0,0,8,6),IsEnabled=!configured&&!RenoGameHdr.NativeHdrEnabled(game)&&items.Any(i=>i.Id=="renodx"),Style=owner.TryFindResource(configured?"Installed":"Primary") as Style};row.Children.Add(configure);configure.Click+=(s,e)=>{if(Busy||RenoDxUi.IsBusy)return;try{review(RenoGameHdr.Prepare(game));}catch(Exception ex){info.Text=L(ex.Message);}};if(RenoGameHdr.Managed(game)){var restore=new Button{Content=L("Restore HDR configuration"),Margin=new Thickness(0,0,8,6)};row.Children.Add(restore);restore.Click+=(s,e)=>{if(Busy||RenoDxUi.IsBusy)return;try{var p=new DlssPlan{Folder=Path.GetDirectoryName(game.Exe),Uninstall=true,Summary=L("Restore HDR configuration")};RenoGameHdr.AttachRestore(game,p);review(p);}catch(Exception ex){info.Text=L(ex.Message);}};}hdr.Children.Add(row);hdr.Children.Add(Dialogs.Text(RenoGameHdr.HdrState(game),12));hdr.Children.Add(Dialogs.Text(L(configured?"Restart the game and verify HDR in a loaded scene.":"RenoDX HDR requires game configuration."),12));}
   string[] ids=dlss?new[]{"opti","nr"}:new[]{"reshade","asi","renodx","mfg"};string[] labels=dlss?new[]{"Remove OptiScaler","Remove Neural Rendering"}:new[]{"Remove ReShade","Remove ASI Loader","Remove RenoDX","Remove MFG"};
   for(int n=0;n<ids.Length;n++){string id=ids[n];if(scope!=null&&(scope=="dll"?id=="opti":id!=scope))continue;addRemove(labels[n],"remove-"+id,()=>review(RemoveGroup(game,id)),items.Any(i=>i.Id==id));}
   foreach(var item in items.Where(i=>!ids.Contains(i.Id))){var current=item;addRemove((item.Id=="native"||item.Id=="streamline"?L("Restore original"):L("Uninstall"))+" · "+item.Name,"remove-"+item.Id,()=>review(ModInventory.Remove(current)),true);}
   if(!dlss&&(scope==null||scope=="reshade"))addRemove("Clean duplicate loaders","remove-duplicates",()=>review(DuplicateLoaders.Prepare(game)),true);
