   foreach(var item in items){var current=item;var checkedItem=ModUpdates.Items.FirstOrDefault(i=>i.Game.Exe==game.Exe&&i.Id==item.Id&&i.File==item.File&&i.Name==item.Name);var row=new StackPanel{Margin=new Thickness(0,0,0,10)};var update=new Button{Content=L(item.Id=="opti"||item.Id=="nr"?"Choose version":item.Id=="addon"?(RenoDx.AddonPage(item.File)!=null?"Update via Nexus":"Import update…"):item.Id=="ue4ss"&&(checkedItem==null||checkedItem.Status=="Installed revision unknown")?"Install latest version":"Update"),MinWidth=120,Margin=new Thickness(8,0,0,0),Tag="update-"+item.Id,IsEnabled=CanUpdate(item,checkedItem)};var text=Dialogs.Text(UpdatePresentation.Summary(item,checkedItem),14);text.Margin=new Thickness(0,3,0,8);UpdatePresentation.Paint(text,checkedItem);row.Children.Add(text);
    if(!new[]{"opti","nr","addon"}.Contains(item.Id))update.Content=UpdatePresentation.Action(item,checkedItem);
    update.Margin=new Thickness(0,0,8,8);UpdatePresentation.ButtonStyle(update,owner,checkedItem!=null&&checkedItem.UpdateAvailable);
    var actions=new WrapPanel();actions.Children.Add(update);var again=new Button{Content=L("Check again"),Margin=new Thickness(0,0,8,8),IsEnabled=!ModUpdates.Checking};actions.Children.Add(again);again.Click+=async(s,e)=>{if(Busy||RenoDxUi.IsBusy)return;again.IsEnabled=false;try{await ModUpdates.RefreshComponent(game,current.Id);}catch(Exception ex){StatusFeedback.Error(info,ex.Message);}finally{if(again.IsLoaded)again.IsEnabled=true;}};row.Children.Add(actions);updates.Children.Add(row);
    update.Click+=async(s,e)=>{if(Busy||RenoDxUi.IsBusy)return;Busy=true;panel.IsEnabled=false;try{if(current.Id=="addon"){Busy=false;string page=RenoDx.AddonPage(current.File);if(page!=null)NexusDownload.Show(owner,game,page,review,current.File,"Control",panel);else{var pick=new Microsoft.Win32.OpenFileDialog{Filter="ReShade add-on|*.addon64",Title=L("Choose the same add-on filename (x64).")};if(pick.ShowDialog(owner)==true)review(RenoDx.ReplaceManualAddon(game,current.File,pick.FileName));}changed();}else if(current.Id=="opti"||current.Id=="nr"){info.Text=L("Choose the version in the main component section, then install.");if(chooseVersion!=null)chooseVersion(current.Id);}else{var plan=await Task.Run(()=>current.Id=="ue4ss"?Ue4ssInstaller.DownloadAndPrepare(game,false):Update(current));Busy=false;review(plan);}render();}catch(Exception ex){info.Text=L(ex.Message);}finally{Busy=false;panel.IsEnabled=true;}};
   }
   updateHeading.Visibility=items.Count==0?Visibility.Visible:Visibility.Collapsed;check.IsEnabled=!ModUpdates.Checking;check.Content=L(ModUpdates.IsChecking(game,scope)?"Checking updates…":"Check again");
  };
  check.Click+=async(s,e)=>{if(Busy)return;try{if(scope==null||scope=="dll")await ModUpdates.Refresh(new[]{game});else await ModUpdates.RefreshComponent(game,scope);}catch(Exception ex){info.Text=L(ex.Message);}};
  var initialReads=ViewReads.Current;int refreshRevision=0;bool subscribed=false;Action refreshAsync=async()=>{int revision=++refreshRevision;try{var reads=new ViewReads(System.Threading.CancellationToken.None);await Task.Run(()=>{using(reads.Enter())ModInventory.Scan(game);});if(panel.IsLoaded&&!Busy&&revision==refreshRevision)using(reads.Enter())render();}catch(Exception ex){if(panel.IsLoaded)info.Text=L(ex.Message);}};Action onChange=()=>panel.Dispatcher.BeginInvoke(new Action(()=>{if(panel.IsLoaded&&!Busy)refreshAsync();}));panel.Loaded+=(s,e)=>{if(!subscribed){ModUpdates.Changed+=onChange;subscribed=true;}if(initialReads!=null){using(initialReads.Enter())render();initialReads=null;}else refreshAsync();};panel.Unloaded+=(s,e)=>{if(subscribed){ModUpdates.Changed-=onChange;subscribed=false;}};render();return panel;
 }
 static DlssPlan Update(ModItem item){var g=item.Game;Core.Closed(g);string origin;
 switch(item.Id){case "reshade":return RenoDx.InstallReShade(g,RenoDx.Fetch(RenoDx.InstalledChannel(g)=="nightly",s=>{},out origin),origin);
 case "renodx":return RenoDx.InstallAddon(g,RenoDx.FetchForGame(g,out origin));
 case "mfg":MfgAddon.Release release;string file=MfgAddon.Fetch(out release);return MfgAddon.Prepare(g,file,release);
 case "asi":return AsiLoader.Prepare(g,AsiLoader.Fetch(),Path.GetFileName(item.File));
 case "effect":return EffectCatalog.Prepare(g,item.Effect,s=>{});
 case "feeder":return NrFeeder.DownloadAndPrepare(g,s=>{});
 case "streamline":return Streamline.Prepare(g,item.File,Streamline.Latest(s=>{}));
 case "native":var dll=DllCatalog.Fetch(item.Library.File).First();return DlssLibraries.Prepare(g,item.Library,DllCatalog.Download(dll,s=>{}));
 default:throw new Exception("No updater for this component.");}
 }
